app.post('/api/auth/team-invite/accept',authLimiter,async(req,res)=>{const email=String(req.body.email||'').trim().toLowerCase(),inviteToken=String(req.body.inviteToken||''),password=String(req.body.password||''),displayName=String(req.body.displayName||email.split('@')[0]).trim().slice(0,100);if(!email||!inviteToken||password.length<10)return res.status(400).json({error:'Invite link, invited email, and a password of at least 10 characters are required.'});const found=(await pool.query('select * from admin_invites where email=$1 and accepted_at is null and expires_at>now()',[email])).rows[0];const candidateHash=crypto.createHash('sha256').update(inviteToken).digest('hex');if(!found||!crypto.timingSafeEqual(Buffer.from(found.token_hash),Buffer.from(candidateHash)))return res.status(403).json({error:'Access denied: no valid invite exists for this email.'});const h=await bcrypt.hash(password,12);const client=await pool.connect();try{await client.query('BEGIN');const existing=(await client.query('select id from users where lower(email)=$1 for update',[email])).rows[0];if(existing){await client.query("UPDATE users SET password_hash=$1,display_name=CASE WHEN display_name IS NULL OR display_name='' THEN $2 ELSE display_name END WHERE id=$3",[h,displayName,existing.id])}else{await client.query("INSERT INTO users(display_name,email,password_hash,role) VALUES($1,$2,$3,'user')",[displayName,email,h])}await client.query("UPDATE admin_team SET status='active' WHERE email=$1",[email]);await client.query("UPDATE admin_invites SET accepted_at=now(),token_hash='accepted' WHERE email=$1",[email]);await client.query('COMMIT')}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}return res.json({message:'Invite accepted. You can now sign in with your new password.'})});
// Admin MFA is optional unless ADMIN_MFA_CODE is explicitly configured.

// Password reset: tokens are hashed in the database, short-lived, single-use, and never returned by the API.
app.post('/api/auth/forgot-password',authLimiter,async(req,res)=>{
  const email=String(req.body?.email||'').trim().toLowerCase();
  if(!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return res.status(400).json({error:'Enter a valid email address.'});
  const generic={message:'If an account exists for that email, a password reset link will be sent.'};
  const user=(await pool.query('select id,email from users where lower(email)=$1',[email])).rows[0];
  if(!user) return res.json(generic);

  const hasBrevo=Boolean(process.env.BREVO_API_KEY && process.env.PASSWORD_RESET_FROM);
  const hasResend=Boolean(process.env.RESEND_API_KEY && process.env.PASSWORD_RESET_FROM);
  if(!hasBrevo && !hasResend) return res.status(503).json({error:'Password reset email is not configured yet. Please contact the site owner.'});

  const raw=crypto.randomBytes(32).toString('hex');
  const tokenHash=crypto.createHash('sha256').update(raw).digest('hex');
  await pool.query('update password_resets set used_at=now() where user_id=$1 and used_at is null',[user.id]);
  await pool.query("insert into password_resets(user_id,token_hash,expires_at) values($1,$2,now()+interval '30 minutes')",[user.id,tokenHash]);

  const base=String(process.env.FRONTEND_URL||'https://primordialstreams.up.railway.app').split(',')[0].replace(/\/$/,'');
  const resetUrl=base+'/#/reset-password/'+raw;
  const html='<div style="font-family:Arial,sans-serif;max-width:520px;margin:auto;color:#172033"><h2>Reset your password</h2><p>We received a request to reset your Primordial Streams password.</p><p><a href="'+resetUrl+'" style="display:inline-block;padding:12px 18px;background:#2f6bff;color:#fff;border-radius:8px;text-decoration:none">Reset password</a></p><p>This link expires in 30 minutes and can only be used once. If you did not request this, ignore this email.</p></div>';
  const text='Reset your Primordial Streams password: '+resetUrl+'\n\nThis link expires in 30 minutes and can only be used once.';

  try {
    if(hasBrevo){
      const mail=await fetch('https://api.brevo.com/v3/smtp/email',{
        method:'POST',
        headers:{accept:'application/json','api-key':process.env.BREVO_API_KEY,'Content-Type':'application/json'},
        body:JSON.stringify({
          sender:{email:process.env.PASSWORD_RESET_FROM,name:process.env.PASSWORD_RESET_FROM_NAME||'Primordial Streams'},
          to:[{email}],
          subject:'Reset your Primordial Streams password',
          htmlContent:html,
          textContent:text
        })
      });
      if(!mail.ok){
        const details=await mail.text().catch(()=> '');
        throw new Error('Brevo '+mail.status+': '+details.slice(0,300));
      }
    } else {
      const mail=await fetch('https://api.resend.com/emails',{
        method:'POST',
        headers:{Authorization:'Bearer '+process.env.RESEND_API_KEY,'Content-Type':'application/json'},
        body:JSON.stringify({
          from:process.env.PASSWORD_RESET_FROM,
          to:[email],
          subject:'Reset your Primordial Streams password',
          html,
          text
        })
      });
      if(!mail.ok){
        const details=await mail.text().catch(()=> '');
        throw new Error('Resend '+mail.status+': '+details.slice(0,300));
      }
    }
  } catch(e) {
    console.error('Password reset email provider error:',e?.message||'Unknown email error');
    await pool.query('update password_resets set used_at=now() where token_hash=$1',[tokenHash]);
    return res.status(502).json({error:'Reset email could not be sent. Please check the email service settings and try again.'});
  }
  return res.json(generic);
});
app.post('/api/auth/reset-password',authLimiter,async(req,res)=>{
  const raw=String(req.body?.token||''),password=String(req.body?.password||'');
  if(!raw || !/^[a-f0-9]{64}$/i.test(raw)) return res.status(400).json({error:'This reset link is invalid. Request a new one.'});
  if(password.length<10) return res.status(400).json({error:'Password must be at least 10 characters long.'});
  const hash=crypto.createHash('sha256').update(raw).digest('hex');
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const reset=(await client.query('select id,user_id from password_resets where token_hash=$1 and used_at is null and expires_at>now() for update',[hash])).rows[0];
    if(!reset){await client.query('ROLLBACK');return res.status(400).json({error:'This reset link has expired or was already used. Request a new one.'});}
    const passHash=await bcrypt.hash(password,12);
    await client.query('update users set password_hash=$1 where id=$2',[passHash,reset.user_id]);
    await client.query('update password_resets set used_at=now() where user_id=$1 and used_at is null',[reset.user_id]);
    await client.query('COMMIT');
    return res.json({message:'Password updated successfully. You can now sign in.'});
  }catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}
});
app.post('/api/auth/login',async(req,res)=>{const{email,password,mfaCode}=req.body;const{rows}=await pool.query('select * from users where email=$1',[String(email||'').toLowerCase()]);if(!rows[0]||!(await bcrypt.compare(password||'',rows[0].password_hash)))return res.status(401).json({error:'Invalid credentials'});if(rows[0].role==='user'&&rows[0].is_banned)return res.status(403).json({error:'This account has been suspended'});if(rows[0].role==='admin'&&process.env.ADMIN_MFA_CODE&&String(mfaCode||'')!==String(process.env.ADMIN_MFA_CODE))return res.status(401).json({error:'Invalid MFA / Security Passcode'});const u=rows[0];delete u.password_hash;await pool.query('update users set last_login=now() where id=$1',[u.id]);const staff=await effectiveStaff(u.email,u.role);if(staff&&staff.status==='active')u.adminRole=staff.role;res.json({token:token(u),user:u})});
