app.post('/api/auth/google',async(req,res)=>{try{const credential=String(req.body.credential||'');if(!process.env.GOOGLE_CLIENT_ID)return res.status(503).json({error:'Google OAuth Client ID is not configured on the server'});if(!credential)return res.status(400).json({error:'Missing Google credential'});const verify=await fetch('https://oauth2.googleapis.com/tokeninfo?id_token='+encodeURIComponent(credential));if(!verify.ok)return res.status(401).json({error:'Google credential could not be verified'});const g=await verify.json();if(g.aud!==process.env.GOOGLE_CLIENT_ID||g.email_verified!=='true'||!g.email)return res.status(401).json({error:'Google account verification failed'});const email=g.email.toLowerCase(),displayName=g.name||g.given_name||email.split('@')[0],avatar=g.picture||'';const hash=await bcrypt.hash(crypto.randomUUID(),12);const result=await pool.query("insert into users(display_name,email,password_hash,avatar_url) values($1,$2,$3,$4) on conflict(email) do update set display_name=excluded.display_name,avatar_url=case when excluded.avatar_url<>'' then excluded.avatar_url else users.avatar_url end returning id,display_name,email,role,created_at,avatar_url",[displayName,email,hash,avatar]);const banned=await pool.query('select is_banned from users where id=$1',[result.rows[0].id]);if(banned.rows[0]?.is_banned)return res.status(403).json({error:'This account has been suspended'});res.json({token:token(result.rows[0]),user:result.rows[0]})}catch(e){console.error('Google sign-in failed',e);res.status(500).json({error:'Google sign-in failed. Please try again.'})}});
