// Studios: public read, staff (owner/admin) add + edit only. There is intentionally no delete route.
function studioSlug(v){return String(v||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function studioIdOf(v){const n=Number(v);if(!Number.isInteger(n)||n<1)return null;const r=await pool.query('select id from studios where id=$1',[n]);return r.rows[0]?n:null}
function cleanStudio(body){const name=String(body?.name||'').trim().slice(0,80);if(!name)return{error:'Studio name is required'};const hasLogo=body&&(body.logoUrl!==undefined||body.logo_url!==undefined);const logo=hasLogo?String(body.logoUrl??body.logo_url??'').trim():undefined;if(logo!==undefined&&(logo.length>1800000||(logo&&!(/^(https?:\/\/|\/)/i.test(logo)||/^data:image\/(webp|png|jpeg|jpg);base64,[A-Za-z0-9+/=]+$/i.test(logo)))))return{error:'Use an image URL or upload a PNG/JPG/WEBP logo under 1.3 MB.'};const hasWebsite=body&&(body.websiteUrl!==undefined||body.website_url!==undefined);const website=hasWebsite?String(body.websiteUrl??body.website_url??'').trim().slice(0,500):undefined;if(website&&!/^https?:\/\//i.test(website))return{error:'Studio website URL must start with http:// or https://'};return{name,logo,website}}
