app.patch('/api/notifications/:id/read',auth,async(req,res)=>{const{rows}=await pool.query('insert into notification_reads(notification_id,user_id) select n.id,$1 from notifications n where n.id=$2 and (n.user_id is null or n.user_id=$1) on conflict(notification_id,user_id) do nothing returning notification_id,read_at',[req.user.id,req.params.id]);if(rows[0])return res.json({id:Number(req.params.id),is_read:true,read_at:rows[0].read_at});const check=await pool.query('select 1 from notification_reads nr join notifications n on n.id=nr.notification_id where nr.notification_id=$1 and nr.user_id=$2 and (n.user_id is null or n.user_id=$2)',[req.params.id,req.user.id]);if(check.rowCount)return res.json({id:Number(req.params.id),is_read:true});return res.sendStatus(404)});
app.get('/api/admin/notifications',admin,async(req,res)=>{const{rows}=await pool.query('select n.id,n.user_id,n.title,n.message,n.notification_type,n.created_at,u.display_name user_name,u.email user_email,coalesce((select count(*)::int from notification_reads nr where nr.notification_id=n.id),0) as read_count from notifications n left join users u on u.id=n.user_id order by n.created_at desc limit 300');res.json(rows)});
app.post('/api/admin/notifications',admin,async(req,res)=>{const title=String(req.body.title||'').trim(),message=String(req.body.message||'').trim(),type=String(req.body.type||'info');const rawIds=Array.isArray(req.body.userIds)?req.body.userIds:(req.body.userId==null||req.body.userId===''?[]:[req.body.userId]);const userIds=[...new Set(rawIds.map(Number))];if(!title||!message)return res.status(400).json({error:'Title and message are required'});if(title.length>120||message.length>2000)return res.status(400).json({error:'Title must be ≤120 characters and message ≤2000 characters'});if(!['info','announcement','release','warning','success'].includes(type))return res.status(400).json({error:'Invalid notification type'});if(rawIds.length>500||userIds.some(id=>!Number.isInteger(id)||id<1))return res.status(400).json({error:'Invalid recipient selection'});if(userIds.length){const check=await pool.query("select count(*)::int count from users where id=any($1::int[]) and role='user'",[userIds]);if(check.rows[0].count!==userIds.length)return res.status(400).json({error:'One or more selected recipients are not registered users'});}const client=await pool.connect();try{await client.query('BEGIN');const targets=userIds.length?userIds:[null];const created=[];for(const userId of targets){const{rows}=await client.query('insert into notifications(user_id,title,message,notification_type,created_by) values($1,$2,$3,$4,$5) returning id,user_id,title,message,notification_type,created_at',[userId,title,message,type,req.user.id]);created.push(rows[0]);}await client.query('COMMIT');res.status(201).json({count:created.length,notifications:created})}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}});
app.delete('/api/admin/notifications/:id',admin,async(req,res)=>{await pool.query('delete from notifications where id=$1',[req.params.id]);res.sendStatus(204)});
app.get('/api/anime/:slug/comments',async(req,res)=>{const{rows}=await pool.query("select c.id,c.content,c.created_at,u.display_name from comments c join anime a on a.id=c.anime_id join users u on u.id=c.user_id where a.slug=$1 and c.status='approved' order by c.created_at desc limit 100",[req.params.slug]);res.json(rows)});
app.post('/api/anime/:slug/comments',auth,async(req,res)=>{const content=String(req.body.content||'').trim();if(!content||content.length>2000)return res.status(400).json({error:'Comment must be 1–2000 characters'});const a=await pool.query('select id from anime where slug=$1',[req.params.slug]);if(!a.rowCount)return res.sendStatus(404);const{rows}=await pool.query("insert into comments(user_id,anime_id,content,status) values($1,$2,$3,'pending') returning id,content,status,created_at",[req.user.id,a.rows[0].id,content]);res.status(201).json({...rows[0],message:'Your comment is awaiting admin approval.'})});
app.get('/api/admin/comments',admin,async(req,res)=>{const status=['pending','approved','rejected'].includes(req.query.status)?req.query.status:null;const sql="select c.id,c.content,c.status,c.created_at,c.reviewed_at,u.id user_id,u.display_name user_name,u.email user_email,a.title anime_title from comments c join users u on u.id=c.user_id join anime a on a.id=c.anime_id "+(status?'where c.status=$1 ':'')+"order by case c.status when 'pending' then 0 when 'approved' then 1 else 2 end,c.created_at desc limit 500";const{rows}=await pool.query(sql,status?[status]:[]);res.json(rows)});
app.patch('/api/admin/comments/:id',admin,async(req,res)=>{const status=String(req.body.status||'');if(!['approved','rejected'].includes(status))return res.status(400).json({error:'Status must be approved or rejected'});const{rows}=await pool.query('update comments set status=$1,reviewed_at=now() where id=$2 returning id,status,reviewed_at',[status,req.params.id]);if(!rows[0])return res.sendStatus(404);res.json(rows[0])});
app.delete('/api/admin/comments/:id',admin,async(req,res)=>{await pool.query('delete from comments where id=$1',[req.params.id]);res.sendStatus(204)});
app.get('/api/admin/overview',admin,async(req,res)=>{try{const {rows}=await pool.query(`
SELECT
 (SELECT count(*)::int FROM anime) AS total_anime,
 (SELECT count(*)::int FROM anime WHERE lower(type) IN ('movie','film')) AS total_movies,
 (SELECT count(*)::int FROM episodes) AS total_episodes,
 (SELECT count(*)::int FROM anime WHERE lower(type) IN ('web-series','web series','webseries')) AS total_web_series,
 (SELECT count(*)::int FROM anime WHERE lower(status) IN ('ongoing','on-air','airing')) AS ongoing_titles,
 (SELECT count(*)::int FROM anime WHERE lower(status) IN ('completed','complete','finished')) AS completed_titles,
 (SELECT count(*)::int FROM anime WHERE lower(status) IN ('upcoming','coming-soon','coming soon')) AS coming_soon_titles,
 (SELECT count(*)::int FROM users WHERE role='user') AS registered_users,
 (SELECT count(*)::int FROM users WHERE role='user' AND created_at >= now()-interval '7 days') AS new_users_7d,
 (SELECT count(DISTINCT user_id)::int FROM progress WHERE updated_at >= now()-interval '30 days') AS active_users_30d,
 (SELECT count(*)::int FROM progress) AS tracked_plays,
 (SELECT count(*)::int FROM watchlist) AS watchlist_additions,
 (SELECT count(*)::int FROM comments WHERE status='pending') AS pending_comments,
 (SELECT count(*)::int FROM video_reports WHERE status='pending') AS pending_player_reports,
 (SELECT count(*)::int FROM notifications n WHERE NOT EXISTS (SELECT 1 FROM notification_reads nr WHERE nr.notification_id=n.id)) AS unread_notifications,
 (SELECT count(*)::int FROM studios) AS total_studios,
 (SELECT count(*)::int FROM anime WHERE is_published=false) AS drafts,
 (SELECT count(*)::int FROM episodes WHERE is_published=false) AS unpublished_episodes
`);const recent=await pool.query('SELECT id,actor_email,actor_role,action,method,path,status_code,created_at FROM admin_activity ORDER BY created_at DESC LIMIT 8');res.set('Cache-Control','no-store');res.json({metrics:rows[0],recentActivity:recent.rows,generatedAt:new Date().toISOString(),definitions:{tracked_plays:'Count of saved playback-progress records; not a verified stream-start count.',active_users_30d:'Distinct users with a playback-progress update in the last 30 days.',new_users_7d:'User accounts created in the last 7 days.'}})}catch(error){console.error('Admin overview query failed:',error.message);res.status(500).json({error:'Unable to load live dashboard metrics.'})}});
app.get('/api/admin/health',admin,async(req,res)=>{const checks={api:true,database:false};try{await pool.query('SELECT 1');checks.database=true;res.set('Cache-Control','no-store');res.json({status:'healthy',checks,checkedAt:new Date().toISOString(),uptimeSeconds:Math.floor(process.uptime())})}catch(error){res.status(503).json({status:'degraded',checks,checkedAt:new Date().toISOString(),error:'Database connectivity check failed.'})}});
app.get('/api/admin/analytics',admin,async(req,res)=>{const p=await pool.query('select count(*)::int count from progress');const u=await pool.query('select count(distinct user_id)::int count from progress');res.json({progressCount:p.rows[0].count,activeViewers:u.rows[0].count});});
app.get('/api/admin/analytics/series',admin,async(req,res)=>{const requested=Number.parseInt(req.query.days,10)||30;const days=Math.max(7,Math.min(90,requested));const{rows}=await pool.query("select d.day::date as date,(select count(*)::int from progress p where p.updated_at>=d.day and p.updated_at<d.day+interval '1 day') as views,(select count(*)::int from users u where u.created_at>=d.day and u.created_at<d.day+interval '1 day') as signups from generate_series(current_date-($1::int-1)*interval '1 day',current_date,interval '1 day') d(day) order by d.day",[days]);const top=await pool.query("select a.id,a.title,a.poster_url,count(p.episode_id)::int streams from progress p join episodes e on e.id=p.episode_id join anime a on a.id=e.anime_id group by a.id order by streams desc limit 5");res.set('Cache-Control','no-store');res.json({days,series:rows,topStreamed:top.rows})});
app.patch('/api/admin/users/:id/ban',admin,async(req,res)=>{const banned=!!req.body.banned;const{rows}=await pool.query("update users set is_banned=$1 where id=$2 and role='user' returning id,email,is_banned",[banned,req.params.id]);if(!rows[0])return res.sendStatus(404);res.json(rows[0])});
app.patch('/api/admin/anime/bulk',admin,async(req,res)=>{const ids=[...new Set((Array.isArray(req.body.ids)?req.body.ids:[]).map(Number))];if(!ids.length||ids.length>500||ids.some(id=>!Number.isInteger(id)||id<1))return res.status(400).json({error:'Select 1–500 valid anime IDs'});if(req.body.action==='publish'||req.body.action==='draft'){const published=req.body.action==='publish';const{rows}=await pool.query('update anime set is_published=$1 where id=any($2::int[]) returning id,is_published',[published,ids]);return res.json({count:rows.length,anime:rows})}if(req.body.action==='delete'){if(req.staffRole==='editor'||req.staffPermissions.canDelete===false)return res.status(403).json({error:'Delete permission required'});const{rows}=await pool.query('delete from anime where id=any($1::int[]) returning id',[ids]);return res.json({count:rows.length})}return res.status(400).json({error:'Invalid bulk action'})});
app.get('/api/admin/schedule',admin,async(req,res)=>{const{rows}=await pool.query("select id,title,year,status,type,created_at from anime order by case status when 'on-air' then 1 when 'ongoing' then 2 when 'upcoming' then 3 else 4 end,created_at desc");res.json(rows)});
app.get('/api/admin/episodes',admin,async(req,res)=>{const{rows}=await pool.query('select e.*,a.title anime_title from episodes e join anime a on a.id=e.anime_id order by a.title,e.season_number,e.episode_number');res.json(rows)});
app.post('/api/admin/episodes/bulk',admin,async(req,res)=>{const x=req.body,animeId=Number(x.animeId),season=Math.max(1,Number(x.seasonNumber)||1),start=Math.max(1,Number(x.startEpisode)||1),count=Number(x.count);if(!Number.isInteger(animeId)||!Number.isInteger(count)||count<1||count>100)return res.status(400).json({error:'Choose an anime and 1–100 episodes'});const template=String(x.videoUrlTemplate||'').trim();if(!template||!/^https?:\/\//i.test(template.replace('{n}',String(start))))return res.status(400).json({error:'Enter a valid video URL template; use {n} for the episode number'});const check=await pool.query('select id from anime where id=$1',[animeId]);if(!check.rowCount)return res.status(404).json({error:'Anime not found'});const client=await pool.connect();try{await client.query('BEGIN');const created=[];for(let i=0;i<count;i++){const n=start+i,url=template.replaceAll('{n}',String(n)),thumb=String(x.thumbnailUrlTemplate||'').replaceAll('{n}',String(n));const{rows}=await client.query('insert into episodes(anime_id,season_number,episode_number,title,video_url,thumbnail_url,is_exclusive,is_published) values($1,$2,$3,$4,$5,$6,$7,$8) returning *',[animeId,season,n,String(x.titlePrefix||'Episode')+' '+n,'__PDI_CUSTOM__:'+url,thumb,!!x.isExclusive,x.isPublished!==false]);created.push(rows[0])}await client.query('COMMIT');res.status(201).json({count:created.length,episodes:created})}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}});
app.post('/api/admin/episodes',admin,async(req,res)=>{const x=req.body;const{rows}=await pool.query('insert into episodes(anime_id,season_number,episode_number,title,video_url,thumbnail_url,is_exclusive,is_published) values($1,$2,$3,$4,$5,$6,$7,$8) returning *',[x.animeId,x.seasonNumber||1,x.episodeNumber,x.title||'',x.videoUrl,x.thumbnailUrl||'',!!x.isExclusive,x.isPublished!==false]);res.status(201).json(rows[0])});
app.put('/api/admin/episodes/:id',admin,async(req,res)=>{const x=req.body;const{rows}=await pool.query('update episodes set anime_id=$1,season_number=$2,episode_number=$3,title=$4,video_url=$5,thumbnail_url=$6,is_exclusive=$7,is_published=$8 where id=$9 returning *',[x.animeId,x.seasonNumber||1,x.episodeNumber,x.title||'',x.videoUrl,x.thumbnailUrl||'',!!x.isExclusive,x.isPublished!==false,req.params.id]);if(!rows[0])return res.sendStatus(404);res.json(rows[0])});
app.delete('/api/admin/episodes/:id',admin,async(req,res)=>{await pool.query('delete from episodes where id=$1',[req.params.id]);res.sendStatus(204)});
